using GestaoClientes.Domain;
namespace GestaoClientes.UnitTests;
public class ClienteTests { static Endereco Endereco(bool principal=true)=>new("01001000","Rua A","1",null,"Centro","São Paulo","SP",principal); [Fact] public void Cliente_valido_inicia_ativo(){var c=new Cliente("Maria","52998224725","maria@a.com","11999999999",new DateOnly(1990,1,1),Endereco());Assert.Equal(StatusCliente.Ativo,c.Status);Assert.Single(c.Enderecos);}[Fact] public void Nascimento_futuro_e_rejeitado()=>Assert.Throws<DomainException>(()=>new Cliente("Maria","52998224725","maria@a.com","1",DateOnly.FromDateTime(DateTime.Today.AddDays(1)),Endereco()));[Fact] public void Novo_principal_substitui_anterior(){var c=new Cliente("Maria","52998224725","maria@a.com","1",new DateOnly(1990,1,1),Endereco());c.AdicionarEndereco(Endereco(true));Assert.Single(c.Enderecos, x => x.Principal);}[Fact] public void Nao_remove_unico_endereco(){var c=new Cliente("Maria","52998224725","maria@a.com","1",new DateOnly(1990,1,1),Endereco());Assert.Throws<DomainException>(()=>c.RemoverEndereco(c.Enderecos.Single().Id));}[Fact] public void Cliente_pode_ser_inativado_e_ativado(){var c=new Cliente("Maria","52998224725","maria@a.com","1",new DateOnly(1990,1,1),Endereco());c.Inativar();Assert.Equal(StatusCliente.Inativo,c.Status);c.Ativar();Assert.Equal(StatusCliente.Ativo,c.Status);}}
